using System; using Inu.Kernel.Networking; namespace Inu.Samples.NetworkClient; public static unsafe class Sample { public static Boolean SendDnsQuery(KernelIpv4Address dns,String host){Byte* packet=stackalloc Byte[512];if(!KernelNetworkApi.BuildDnsQuery(packet,512,0x2500,host,KernelDnsRecordType.A,out UInt32 length))return false;if(!KernelNetworkApi.CreateSocket(KernelSocketType.Datagram,out KernelSocketHandle s))return false;Boolean ok=KernelNetworkApi.SendUdp(s,new KernelIpv4Endpoint(dns,53),packet,length);KernelNetworkApi.Close(s);return ok;} }
